  "ra.w.document-retention.d": "Document-retention language appears. Review the surrounding wording to determine whether this is a requirement, prohibition or example.",
  "ra.w.document-retention.r": "Ask whether originals must be surrendered, for how long, and whether copies are sufficient.",
  "ra.w.unpaid-overtime.t": "Overtime-pay wording to review",
  "ra.w.unpaid-overtime.d": "An uncompensated-overtime phrase appears. Confirm the full context before interpreting it as an obligation.",
  "ra.w.unpaid-overtime.r": "Request written overtime hours, approval rules and compensation terms.",
  "ra.w.scam-gift-card-crypto.t": "Unusual payment method mentioned",
  "ra.w.scam-gift-card-crypto.d": "Gift cards, cryptocurrency or money-transfer services are a common way to collect money from job seekers. Genuine employers normally pay wages into a bank account and do not ask applicants to pay this way.",
  "ra.w.scam-gift-card-crypto.r": "Do not send money or card codes. Ask for the payment purpose in writing and check the company through an independent channel.",
  "ra.w.scam-pay-to-start.t": "Payment requested before work or a contract",
  "ra.w.scam-pay-to-start.d": "Wording asks for money before the job starts or before a contract is issued.",
  "ra.w.scam-pay-to-start.r": "Ask who receives the money, why, and whether it is refundable, in writing, before paying anything.",
  "ra.w.scam-guaranteed-abroad.t": "Guaranteed job or visa claim",
  "ra.w.scam-guaranteed-abroad.d": "No agent can lawfully guarantee a job abroad, a visa or a work permit. Guarantees combined with fees are a recognised warning sign.",
  "ra.w.scam-guaranteed-abroad.r": "Check the agency's licence with your government's foreign-employment regulator and the employer directly.",
  "ra.w.scam-off-platform-chat.t": "Hiring conducted only through a chat app",
  "ra.w.scam-off-platform-chat.d": "The offer moves the conversation to a private chat app. Real recruiters often use these apps too, so this alone proves nothing, but it removes records and company checks.",
  "ra.w.scam-off-platform-chat.r": "Ask for an email from the company's own domain and a contract before sharing documents.",
  "ra.w.scam-sensitive-data-early.t": "Sensitive credentials or codes requested",
  "ra.w.scam-sensitive-data-early.d": "Bank logins, PINs and one-time codes are never needed to hire someone.",
  "ra.w.scam-sensitive-data-early.r": "Do not share them with anyone. Contact your bank if you already did.",
  "ra.w.scam-urgency.t": "Pressure to act immediately",
  "ra.w.scam-urgency.d": "A very short deadline leaves no time to check the employer.",
  "ra.w.scam-urgency.r": "Take the time to verify the company; genuine offers can wait a reasonable period.",
  "ra.w.scam-unrealistic-pay.t": "Very high pay for no experience",
  "ra.w.scam-unrealistic-pay.d": "High daily or weekly pay for no experience or qualifications is a common lure.",
  "ra.w.scam-unrealistic-pay.r": "Compare with the usual pay for the role and ask exactly what work is done and who pays.",
  "ra.w.scam-free-mail-company.t": "A company role using a free email address",
  "ra.w.scam-free-mail-company.d": "The contact is on a free email service although the message speaks for a company. Small employers and individual recruiters do this legitimately, so it is a prompt to verify, not a finding.",
  "ra.w.scam-free-mail-company.r": "Ask for an address on the company's own domain, then confirm the company independently.",
  "ra.q.q-pay-date": "On which date of each month will salary be transferred or disbursed?",
  "ra.q.q-overtime": "If work exceeds the agreed weekly hours, what is the overtime payment rate?",
  "ra.q.q-equipment": "Are necessary work tools, safety equipment, or uniforms provided by the company?",
