  "re.intro": "පහත බඳවා ගැනීමේ නිලධාරීන් ඔබේ සංවිධානය සැබවින්ම නියෝජනය කරන්නේදැයි මිනිසුන් විමසා ඇත. අවසර ඇතැයි ඔබ දන්නා අය පමණක් තහවුරු කරන්න; නැති අයට විරුද්ධ වන්න. ඔබේ තීරණය ඔබේ නම සහ වේලාව සමඟ සටහන් වේ, ඉවත් කළ හැක, තහවුරු කිරීමක් කල් ඉකුත් වේ. ඇසුවේ කවුදැයි ඔබට නොපෙනේ.",
