  "im.pdf.readOne": "පිටු {total} න් {read} ක් කියවා ඇත.",
  "ev.tooBig": "ලේඛනය බයිට් 16,000 ට වැඩි නොවිය යුතුය.",
  "ev.slots": "මෙම ලේඛනයට සාක්ෂි ස්ථාන {needed} ක් අවශ්‍යයි; {left} ක් ඉතිරිය. කෙටි ලේඛනයක් භාවිත කරන්න හෝ ප්‍රකාශයක් ඉවත් කරන්න.",
