  "ev.intro": "UTF-8 .txt ගොනුවක් දේශීයව කියවා එහි උපුටා ගැනීම් සමාලෝචනය කරන්න. පෞද්ගලික වැඩ කෙටුම්පත සුරකින තුරු කිසිවක් නොයවයි. මුල් ගොනුව උඩුගත කිරීම හෝ රඳවා ගැනීමක් නොවේ; ආයාත කළ පෙළ ස්වාධීනව සත්‍යාපනය කර නැත.",
