  "au.reg.checkInbox": "ඔබේ ඉන්බොක්සය පරීක්ෂා කරන්න",
  "au.reg.sentStatus": "මෙම ලිපිනයට ලියාපදිංචිය ලබා ගත හැකි නම්, තහවුරු කිරීමේ සබැඳියක් සඳහා ඔබේ විද්‍යුත් තැපෑල පරීක්ෂා කරන්න. පවතින ගිණුම්වලට පුරනය විය හැක.",
  "au.reg.sentNext": "සබැඳිය විවෘත කර, ඔබේ විද්‍යුත් තැපෑල තහවුරු කර, ඔබේ පැතිකඩ සම්පූර්ණ කරන්න. නොපැමිණියේ නම් ස්පෑම් පරීක්ෂා කරන්න.",
  "au.reg.checkingLink": "ඔබේ සබැඳිය පරීක්ෂා කරමින්…",
  "au.reg.openEmail": "ඔබේ සත්‍යාපන විද්‍යුත් තැපෑල විවෘත කරන්න",
  "au.reg.linkExpired": "මෙම සබැඳිය කල් ඉකුත් වී ඇත",
  "au.reg.linkUnusable": "මෙම සබැඳිය භාවිත කළ නොහැක",
  "au.reg.waitFormat": "සබැඳියේ ආකෘතිය පරීක්ෂා කරන තෙක් රැඳී සිටින්න.",
  "au.reg.useLatest": "ඔබේ ඉන්බොක්සයේ නවතම තහවුරු කිරීමේ සබැඳිය භාවිත කරන්න. එය නැතිනම් හෝ තවදුරටත් ක්‍රියා නොකරන්නේ නම්, පහතින් නව විද්‍යුත් තැපෑලක් ඉල්ලන්න. දැනටමත් තහවුරු කළාද? ඉදිරියට යාමට පුරන්න.",
  "au.reg.accountType": "{kind} ගිණුම",
