  "au.reg.requesting": "විද්‍යුත් තැපෑල ඉල්ලමින්…",
  "au.reg.resendIn": "නැවත යැවීම තත්පර {seconds} කින් ලබා ගත හැක",
  "au.reg.resend": "සත්‍යාපන විද්‍යුත් තැපෑල නැවත යවන්න",
  "au.reg.resendNote": "ඉල්ලීම් අතර අවම වශයෙන් විනාඩියක් රැඳී සිටින්න. විද්‍යුත් තැපැල් බෙදාහැරීමට විනාඩි කිහිපයක් ගත විය හැක.",
  "au.reg.resendWait": "තවත් විද්‍යුත් තැපෑලක් ඉල්ලීමට පෙර විනාඩියක් රැඳී සිටින්න.",
  "au.reg.resendDone": "මෙම ලිපිනයට තහවුරු නොකළ ගිණුමක් ඇත්නම්, නව සත්‍යාපන විද්‍යුත් තැපෑලක් ඉල්ලා ඇත. ඔබේ ඉන්බොක්සය සහ ස්පෑම් බහාලුම පරීක්ෂා කරන්න.",
  "au.reg.resendFailed": "තවත් විද්‍යුත් තැපෑලක් ඉල්ලිය නොහැකි විය.",
  "au.reg.mismatch": "මුරපද නොගැලපේ. මුරපද ක්ෂේත්‍ර දෙකම පරීක්ෂා කරන්න.",
  "au.reg.needName": "ඉදිරියට යාමට ඔබේ නම ඇතුළත් කරන්න.",
  "au.reg.openLink": "ඔබේ විද්‍යුත් තැපෑලේ සත්‍යාපන සබැඳිය විවෘත කරන්න, නැතහොත් පහතින් නව සබැඳියක් ඉල්ලන්න.",
  "au.reg.noSession": "ඔබේ සැසිය ස්ථාපිත කළ නොහැකි විය. කරුණාකර පුරන්න හෝ නව විද්‍යුත් තැපෑලක් ඉල්ලන්න.",
  "au.reg.needDisplay": "ඉදිරියට යාමට ප්‍රදර්ශන නමක් ඇතුළත් කරන්න.",
  "au.reg.linkInvalid": "මෙම සත්‍යාපන සබැඳිය වලංගු නොවේ හෝ කල් ඉකුත් වී ඇත. පහතින් තවත් විද්‍යුත් තැපෑලක් ඉල්ලන්න, නැතහොත් ඔබේ ලිපිනය දැනටමත් තහවුරු කර ඇත්නම් පුරන්න.",
  "au.reg.cannotContinue": "ඉදිරියට යාමට නොහැකි විය.",
  "au.backToSignIn": "පුරනයට ආපසු",
  "au.rec.sentTitle": "ඔබේ ඉන්බොක්සය පරීක්ෂා කරන්න",
  "au.rec.sentStatus": "මෙම ලිපිනයට ගිණුමක් ඇත්නම්, ප්‍රතිසාධන සබැඳියක් සඳහා එහි ඉන්බොක්සය පරීක්ෂා කරන්න. මෙහි ගිණුම් තොරතුරු හෙළි නොකෙරේ.",
  "au.rec.sentNote": "ස්පෑම් පරීක්ෂා කර බෙදාහැරීමට විනාඩි කිහිපයක් ලබා දෙන්න.",
