  "ai.backupIntro": "පළමු සැපයුම්කරුට පිළිතුරු දිය නොහැකි නම්, සමාලෝචනය කළ එම පෙළ ඔබ මෙහි තෝරන උපස්ථයකට යා හැක. ඔබ ටික් නොකරන සැපයුම්කරුවෙකුට කිසිවක් නොයවයි. සෑම එකකටම තමන්ගේම කලාපයක් සහ දත්ත භාවිත කොන්දේසි ඇත.",
