  "pv.unavailable": "පෞද්ගලිකත්ව ඉල්ලීම් ලබා ගත නොහැක.",
  "pv.reviewRecorded": "සමාලෝචන සිදුවීම සටහන් කළා. මෙම ක්‍රියාව නිර්යාතයක් හෝ මකා දැමීමක් ක්‍රියාත්මක නොකරයි.",
