  "pv.withdrawFail": "ඉල්ලීම ඉවත් කළ නොහැකි විය.",
  "pv.intro": "ප්‍රවේශ, නිවැරදි කිරීම්, අක්‍රිය කිරීම් සහ මකා දැමීමේ ඉල්ලීම් අතින් සමාලෝචනය අවශ්‍ය වේ. ඉල්ලීමක් ඉදිරිපත් කිරීමෙන් දත්ත නිර්යාත, ඔබේ ගිණුම අක්‍රිය හෝ වාර්තා මකා නොදමයි. විගණන සහ බෙදාගත් වාර්තා රඳවා ගැනීම වෙන වෙනම සමාලෝචනය කළ යුතුයි.",
  "pv.operatorNote": "සමාලෝචනයට ඔබට පවරන ලද පෞද්ගලිකත්ව හැකියාව සහ සත්‍යාපිත සත්‍යාපක සැසිය පමණක් ඉඩ දෙයි. අනුමත අතින් ක්‍රියා පටිපාටිය සම්පූර්ණ වන තුරු ඉටු කළ ලෙස සලකුණු නොකරන්න. සංවේදී නොවන අභ්‍යන්තර යොමුවක් සටහන් කරන්න, නිර්යාත කළ දත්ත හෝ බාගැනීම් සබැඳියක් කිසිවිටෙක නොවේ.",
  "pv.kind": "පෞද්ගලිකත්ව ඉල්ලීම් වර්ගය",
  "pv.k.access": "මගේ තොරතුරු වෙත ප්‍රවේශය",
  "pv.k.correction": "මගේ තොරතුරු නිවැරදි කරන්න",
  "pv.k.deactivation": "ගිණුම අක්‍රිය කිරීම ඉල්ලන්න",
  "pv.k.deletion": "මකා දැමීමේ සමාලෝචනය ඉල්ලන්න",
  "pv.scope": "ඉල්ලීමේ විෂය පථය",
  "pv.scopeNote": "වාර්තා හෝ ගැටලුව කෙටියෙන් විස්තර කරන්න. මුරපද, අනන්‍යතා ලේඛන හෝ සංවේදී රැකියා විස්තර ඇතුළත් නොකරන්න. ඔබේ ඉල්ලීම ඔබට සහ අවසර ලත් පෞද්ගලිකත්ව සමාලෝචකයින්ට පෙනේ.",
  "pv.submit": "පෞද්ගලිකත්ව ඉල්ලීම ඉදිරිපත් කරන්න",
  "pv.loading": "පෞද්ගලිකත්ව ඉල්ලීම් පූරණය කරමින්…",
  "pv.none": "පෙන්වීමට පෞද්ගලිකත්ව ඉල්ලීම් නැත.",
