  "pv.withdraw": "මෙම ඉල්ලීම ඉවත් කරන්න",
  "pv.refresh": "පෞද්ගලිකත්ව ඉල්ලීම් නැවුම් කරන්න",
  "pv.next": "ඊළඟ පෞද්ගලිකත්ව ඉල්ලීම්",
  "sec.unavailable": "ගිණුම් ආරක්ෂාව ලබා ගත නොහැක.",
  "sec.verified": "මෙම සැසිය සඳහා සත්‍යාපකය තහවුරු කළා.",
  "sec.deactivatedAll": "ඔබේ ORYQEN ගිණුම අක්‍රිය කළ අතර සියලු නැවුම් කිරීමේ සැසි පිටවිය.",
  "sec.deactivatedPartial": "ඔබේ ORYQEN ගිණුම අක්‍රිය කළා. සත්‍යාපන සැසි අවලංගු කිරීම තහවුරු කළ නොහැකි විය, නමුත් යෙදුම් ප්‍රවේශය අවහිර කර ඇත.",
  "sec.aria": "ගිණුම් ආරක්ෂාව",
  "sec.title": "සත්‍යාපකය සහ ගිණුම් ප්‍රවේශය",
  "sec.doneNote": "පවතින ගිවිසුම්, රැකියා ඉතිහාසය සහ විගණන වාර්තා රඳවා ගනී. මෙය මකා දැමීමක් නොවේ. ස්වයං-සේවා නැවත සක්‍රිය කිරීම ලබා ගත නොහැක.",
  "sec.returnSignIn": "පුරනයට ආපසු",
  "sec.intro": "සංවේදී ගිණුම් ක්‍රියා සඳහා සත්‍යාපක යෙදුමක් භාවිත කරන්න. මෙය SMS නොයවන අතර සේවායෝජක හෝ සමාලෝචක අවසර ලබා නොදෙයි.",
  "sec.loading": "ගිණුම් ආරක්ෂාව පූරණය කරමින්…",
  "sec.setup": "ගිණුම් සත්‍යාපකය සකසන්න",
  "sec.setupKey": "මෙම පෞද්ගලික සැකසුම් යතුර ඔබේ සත්‍යාපක යෙදුමට එක් කරන්න. එය පෙන්වන්නේ ලියාපදිංචියේදී පමණි; එය බෙදා නොගන්න.",
  "sec.code": "ගිණුම් සත්‍යාපක කේතය",
  "sec.verify": "ගිණුම් සත්‍යාපකය තහවුරු කරන්න",
  "sec.deactSummary": "මගේ ගිණුම අක්‍රිය කරන්න",
  "sec.deactNote": "අක්‍රිය කිරීම ඔබේ ORYQEN ප්‍රවේශය සහ ඔබේ බෙදාගත් ගමන් බලපත්‍රයට ලබන්නන්ගේ ප්‍රවේශය අවහිර කරයි. කලින් බාගත් පිටපත් ආපසු ගත නොහැක. ගිවිසුම් සහ විගණන ඉතිහාසය රඳවා ගනී; අක්‍රිය කිරීම දත්ත මකා නොදමන අතර ඓතිහාසික තහවුරු කිරීම් ඉවත් නොකරයි. ස්වයං-සේවා නැවත සක්‍රිය කිරීම ලබා ගත නොහැක. මකා දැමීමේ සමාලෝචනය සඳහා අක්‍රිය කිරීමට පෙර පෞද්ගලිකත්ව ඉල්ලීම් භාවිත කරන්න.",
