  "set.refNote": "මෙම යොමුව ඔබේ අපේක්ෂිත සේවායෝජකයාට හෝ ගමන් බලපත්‍ර යවන්නාට පමණක් දෙන්න. එය ඔබේ ගිණුම හඳුනාගන්නා අතර ප්‍රවේශයක් නොදෙයි. ඔබේ මුරපදය හෝ සත්‍යාපක කේත කිසිවිටෙක බෙදා නොගන්න.",
  "set.jobAlerts": "රැකියා දැනුම්දීම්",
  "set.hoursReminders": "පැය මතක් කිරීම්",
  "set.notAvailable": "ලබා ගත නොහැක",
  "set.inAppNote": "යෙදුම තුළ ක්‍රියාකාරකම්වලට සුරකින ලද දීමනා සහ සංවිධාන තීරණ ඇතුළත් වේ. විද්‍යුත් තැපැල් සහ තල්ලු බෙදාහැරීම සම්බන්ධ කර නැත. ඔබේ පෞද්ගලික ගිණුම් විස්තර ප්‍රසිද්ධියේ ලැයිස්තුගත නොකෙරේ.",
