  "set.signOutFail": "පිටවීම අසාර්ථක විය.",
  "oc.error": "සංසන්දනය ලබා ගත නොහැක. මෙම දීමනා වලින් එකක් තවදුරටත් ප්‍රවේශ විය නොහැකි විය හැක. ඔබේ සම්බන්ධතාව පරීක්ෂා කරන්න හෝ වෙනත් දීමනා තෝරන්න.",
  "oc.aria": "දීමනා සංසන්දනය",
  "oc.title": "සුරකින ලද කොන්දේසි සසඳන්න",
  "oc.intro": "මේවා දැන් පූරණය කළ සුරකින ලද සංශෝධන වේ. ප්‍රමාණ සටහන් කළ ආකාරයෙන් පෙන්වයි: මුදල් ඒකක, වැටුප් කාල සහ දළ/ශුද්ධ පදනම වෙනස් විය හැක. මෙම සංසන්දනය සේවායෝජකයින් ශ්‍රේණිගත නොකරන අතර ඔවුන්ගේ ප්‍රකාශ සත්‍යාපනය නොකරයි.",
  "oc.loading": "අවසර ලත් දීමනා සංශෝධන පූරණය කරමින්…",
  "oc.retry": "සංසන්දනය නැවත උත්සාහ කරන්න",
  "oc.diffOnly": "වෙනස් කොන්දේසි පමණක් පෙන්වන්න",
