  "oh.intro": "කියවීමට පමණක් සුරකින ලද කොන්දේසි. ඓතිහාසික සංශෝධන වත්මන් ගිවිසුම් තහවුරු කිරීමක් හෝ සත්‍යාපනයක් නොවේ.",
