  "cf.appealNote": "අභියාචනයක් වත්මන් ඉදිරිපත් කළ සංශෝධනයට එරෙහිව නව නඩුවක් විවෘත කරයි. එය මුල් තීරණය සහ සියලු ගමන් බලපත්‍ර බැහැර කිරීම් ආරක්ෂා කරයි. ඉවත් කළ හෝ කෙටුම්පත් වාර්තා මුලින් නිවැරදි කිරීමේ ක්‍රියාවලිය අනුගමනය කළ යුතුයි.",
