  "cf.saveResponse": "ප්‍රතිචාරය සුරකින්න",
  "cf.next": "ඊළඟ ලිපි හුවමාරු පිටුව",
  "cf.reload": "ලිපි හුවමාරුව නැවත පූරණය කරන්න",
  "nf.loadError": "ක්‍රියාකාරකම් පූරණය කළ නොහැකි විය. පුරා සම්බන්ධ වූ විට නැවත උත්සාහ කරන්න.",
