  "nf.aria": "ගිණුම් දැනුම්දීම්",
  "nf.subtitle": "දීමනා, ගිවිසුම්, රැකියා සහ සංවිධාන ක්‍රියාකාරකම්",
  "nf.intro": "යෙදුම තුළ ක්‍රියාකාරකම් පමණි. විද්‍යුත් තැපැල් සහ තල්ලු බෙදාහැරීම සම්බන්ධ කර නැත. ඓතිහාසික අනුමත දැනුම්දීම් වත්මන් අධිකාරිය තහවුරු නොකරයි. වත්මන් තත්ත්වය සඳහා අදාළ වාර්තාව විවෘත කරන්න.",
  "nf.prefs": "දැනුම්දීම් මනාප (මෙම උපාංගය)",
  "nf.prefsNote": "මෙම පෝෂකය මෙම උපාංගයේ පෙන්වන ක්‍රියාකාරකම් වර්ග තෝරන්න. සඟවූ ක්‍රියාකාරකම් තවමත් සටහන් වන අතර කිසිවිටෙක මකා නොදමයි. නඩු ප්‍රතිචාර සහ අභියාචන සැඟවිය නොහැක, මන්ද එකක් මග හැරීමෙන් ඔබට නියමිත දිනයක් අහිමි විය හැක.",
  "nf.c.offers": "දීමනා සංශෝධන",
  "nf.c.agreements": "ගිවිසුම් තීරණ",
  "nf.c.work": "වැඩ වාර්තා තීරණ සහ අඛණ්ඩතා සිදුවීම්",
  "nf.c.organization": "සංවිධාන තීරණ",
  "nf.c.cases": "නඩු ප්‍රතිචාර සහ අභියාචන",
  "nf.loading": "ක්‍රියාකාරකම් පූරණය කරමින්…",
