  "gd.historyFail": "මාර්ගෝපදේශ ඉතිහාසය ලබා ගත නොහැක.",
  "gd.loadFail": "ඉතිහාසය ලබා ගත නොහැක. සම්බන්ධිත දීමනා වෙත ප්‍රවේශය පරීක්ෂා කරන්න.",
  "gd.deleted": "සංවාදය මකා දැමුවා. එහි ප්‍රශ්න සහ පිළිතුරු ස්ථිරවම ඉවත් කළා.",
  "gd.alreadyEmpty": "එම සංවාදය දැනටමත් හිස්ව තිබුණි.",
  "gd.deleteFail": "සංවාදය මකා දැමිය නොහැකි විය. නැවත උත්සාහ කරන්න; කිසිවක් මකා දැමූ බව වාර්තා නොවීය.",
  "gd.invalid": "ප්‍රශ්නයක් සහ, සපයන්නේ නම්, වලංගු සුරකින ලද දීමනා හැඳුනුමක් ඇතුළත් කරන්න.",
  "gd.saveFail": "පිළිතුර සුරැකිය නොහැකි විය. ආරක්ෂිතව යථා තත්ත්වයට පත් කිරීමට එම ප්‍රශ්නයම නැවත උත්සාහ කරන්න.",
  "gd.aria": "පෞද්ගලික මාර්ගෝපදේශය",
  "gd.notice": "සජීවී AI මාර්ගෝපදේශ ලබා ගත නොහැක. මෙය රීති පදනම් කළ නිෂ්පාදන මාර්ගෝපදේශයකි, AI-ජනනය කළ පිළිතුරක් හෝ නීතිමය උපදෙසක් නොවේ. එය ඔබේ ප්‍රශ්නය සටහන් කර ඔබ තෝරන මාතෘකාවට පොදු මාර්ගෝපදේශ සපයයි; අත්තනෝමතික ප්‍රශ්න අර්ථ නොදක්වන අතර ක්‍රියා සිදු නොකරයි.",
  "gd.privacy": "මෙම ඉතිහාසයට ප්‍රවේශ විය හැක්කේ ඔබට පමණි. මුරපද, හැඳුනුම් අංක හෝ වෙනත් අනවශ්‍ය පුද්ගලික විස්තර ඇතුළත් නොකරන්න.",
