  "gd.limit": "මෙම සංවාදය පණිවිඩ 100 ට ළඟා වී ඇත. දිගටම කරගෙන යාමට නව සංවාදයක් ආරම්භ කරන්න.",
  "rp.summary": "මේ ගැන ගැටලුවක් වාර්තා කරන්න",
  "rp.intro": "වාර්තා පෞද්ගලිකව ORYQEN සමාලෝචකයින් වෙත යයි. ඔබ නම් කරන පුද්ගලයා හෝ සංවිධානයට ඒවා කිසිවිටෙක නොපෙන්වයි, වාර්තාවක් මත පදනම්ව ORYQEN කිසිවෙකුට චෝදනා නොකරයි. මුරපද, හැඳුනුම් අංක හෝ ලේඛන ඇතුළත් නොකරන්න.",
