  "sum.notAgreement": "මෙම සාරාංශය ගිවිසුමක්, අත්සනක් හෝ සේවායෝජක සත්‍යාපනයක් නොවේ. එය මුල් දීමනාව සමඟ තබා ගන්න.",
  "sum.integrity": "සුරකින ලද කොන්දේසි චෙක්සම්",
