  "offers.search": "පූරණය කළ දීමනා තනතුරෙන් සොයන්න",
  "offers.searchNote": "සෙවීමක් හෝ පෙරහනක් භාවිතා කරන විට ඔබේ ඉතිරි සුරැකි දීමනා මුලින් පූරණය වේ; එබැවින් පැරණි ඒවා ද ඇතුළත් වේ (උපරිම 200).",
