  "tl.title": "මගේ රැකියා කාල රේඛාව",
  "tl.intro": "ඔබ වාර්තා කළ රැකියා සහ ඔබේ වැඩ වාර්තා දිනය අනුව. මෙම දසුනෙන් කිසිවක් එකතු කිරීම හෝ සත්‍යාපනය නොකෙරේ: සෑම පේළියක්ම තමන්ගේ තත්ත්වය රඳවා ගනී.",
  "tl.empty": "තවම පෙන්වීමට කිසිවක් නැත. ඔබේ රැකියා ඉතිහාසයට රැකියාවක් එක් කරන්න හෝ වැඩ වාර්තාවක් සාදන්න.",
  "tl.error": "කාල රේඛාව පූරණය කළ නොහැකි විය. සම්බන්ධ වූ විට නැවත උත්සාහ කරන්න.",
  "tl.present": "දැනට",
  "tl.selfReported": "ස්වයං-වාර්තා කළ, සත්‍යාපනය නොකළ",
