  "reminders.shareOne": "ඔබ බෙදාගත් ගමන් බලපත්‍ර සබැඳියක් දින {days} කින් ({date}) අවසන් වේ. ලබන්නාට තවමත් අවශ්‍ය නම් නැවත බෙදාගන්න.",
  "reminders.shareMany": "ඔබ බෙදාගත් ගමන් බලපත්‍ර සබැඳියක් දින {days} කින් ({date}) අවසන් වේ. ලබන්නාට තවමත් අවශ්‍ය නම් නැවත බෙදාගන්න.",
