  "adm.refresh": "සොයන්න / නැවුම් කරන්න",
  "adm.rangeNote": "සිදුවීම් දින UTC භාවිත කරයි; උපරිම පරාසය දින 92කි. පුද්ගල, සංවිධාන, ප්‍රවේශ සහ සැකසුම් නාමාවලිවල පැරණි වාර්තා ඇතුළත් වේ. එකතු කිරීම් සියලු සටහන් කාලය පිළිබිඹු කරයි; ප්‍රවණතා දින පෙරහන අනුගමනය කරයි.",
