  "im.docx.intro": "ඔබේ .docx ගොනුව මෙම උපාංගයේම පවතී; සුරකින්නේ හෝ උඩුගත කරන්නේ නැත. 5 MB දක්වා ප්‍රධාන පෙළ පමණක් කියවයි. උපුටා ගත් පෙළ අසම්පූර්ණ හෝ අනුපිළිවෙළ වෙනස් විය හැක, එබැවින් ඉදිරියට යාමට පෙර සමාලෝචනය කරන්න.",
