  "im.docx.e.type": "එම ගොනුව .docx ලේඛනයක් නොවේ. .docx ගොනුවක් තෝරන්න හෝ පෙළ අලවන්න.",
  "im.docx.e.size": "5 MB ට අඩු Word ලේඛනයක් තෝරන්න.",
  "im.docx.e.legacy": "පැරණි .doc ගොනු සහාය නොදක්වයි. ගොනුව .docx ලෙස සුරකින්න හෝ පෙළ අලවන්න.",
  "im.docx.e.unreadable": "මෙම ලේඛනය කියවිය නොහැකි විය. වෙනත් ගොනුවක් උත්සාහ කරන්න හෝ පෙළ අලවන්න.",
  "im.docx.e.too_large": "මෙම ලේඛනය මෙහි කියවීමට විශාල වැඩියි. ඔබට අවශ්‍ය කොටස අලවන්න.",
  "im.docx.e.no_text": "මෙම ලේඛනයේ පෙළක් හමු නොවීය. ඒ වෙනුවට පෙළ අලවන්න.",
  "opc.title": "සුරකින ලද ලැයිස්තු සසඳන්න",
  "opc.intro": "එක් එක් ලැයිස්තුව සඳහන් කරන දේ සමීපව බැලීමට ඔබේ සුරකින ලද ලැයිස්තු {max} දක්වා තෝරන්න. කිසිවක් ශ්‍රේණිගත නොකෙරේ, කිසිවක් සුරකින්නේ නැත.",
  "opc.pick": "සැසඳිය යුතු ලැයිස්තු",
  "opc.needTwo": "අවම වශයෙන් ලැයිස්තු දෙකක් තෝරන්න.",
  "opc.caption": "තෝරාගත් ලැයිස්තු සසඳන ලදී",
  "opc.field": "විස්තරය",
  "opc.differs": "වෙනස්",
  "opc.payNote": "මෙම ලැයිස්තු වෙනස් මුදල් ඒකක හෝ කාල පරිච්ඡේද වලින් වැටුප සඳහන් කරයි. වැටුප සඳහන් කළ ආකාරයෙන්ම පෙන්වයි, පරිවර්තනය නොකෙරේ, එබැවින් සෘජුව සැසඳිය නොහැක.",
  "opc.row.company": "සංවිධානය",
  "opc.row.location": "ස්ථානය",
  "opc.row.workMode": "සැකැස්ම",
  "opc.row.pay": "වැටුප",
  "opc.row.expires": "කල් ඉකුත් වේ",
  "au.rec.checkingLink": "ඔබේ සබැඳිය පරීක්ෂා කරමින්…",
  "au.rec.waitFormat": "සබැඳියේ ආකෘතිය පරීක්ෂා කරන තෙක් රැඳී සිටින්න.",
  "au.rec.openEmail": "ඔබේ විද්‍යුත් තැපෑලේ සබැඳිය විවෘත කරන්න",
  "au.rec.linkExpired": "මෙම සබැඳිය කල් ඉකුත් වී ඇත",
  "au.rec.linkUnusable": "මෙම සබැඳිය භාවිත කළ නොහැක",
  "au.rec.linkUnsupported": "මෙම සබැඳිය මෙහි සම්පූර්ණ කළ නොහැක",
  "au.rec.unsupportedBody": "මෙම විද්‍යුත් තැපැල් සබැඳිය වෙනත් පුරනය වීමේ ක්‍රමයක් සඳහා සාදන ලද්දකි. නව මුරපද යළි සැකසීමේ විද්‍යුත් තැපෑලක් ඉල්ලා අලුත්ම එක විවෘත කරන්න.",
  "au.rec.useLatest": "අප එවූ අලුත්ම විද්‍යුත් තැපෑල භාවිත කරන්න, නැතහොත් අලුත් එකක් ඉල්ලන්න. සබැඳියක් එක් වරක් සහ සීමිත කාලයක් පමණක් ක්‍රියා කරයි.",
  "au.rec.requestNew": "නව යළි සැකසීමේ විද්‍යුත් තැපෑලක් ඉල්ලන්න",
  "au.rec.linkUsedError": "මෙම යළි සැකසීමේ සබැඳිය වලංගු නොවේ, කල් ඉකුත් වී ඇත, නැතහොත් දැනටමත් භාවිත කර ඇත. අලුත් එකක් ඉල්ලන්න.",
  "au.rec.inviteNote": "ඔබට ORYQEN වෙත ආරාධනා කර ඇත. ඔබේ මුරපදය තේරීමට ඉදිරියට යන්න. මෙම පිටුව විවෘත කිරීමෙන් පමණක් ඔබේ ආරාධනාව භාවිත නොවේ.",
  "au.rec.samePassword": "ඔබගේ වත්මන් මුරපදයට වඩා වෙනස් මුරපදයක් තෝරන්න. ඔබේ සබැඳිය තවමත් වලංගුයි.",
  "au.rec.weakPassword": "එම මුරපදය අනුමාන කිරීමට පහසු හෝ ඉතා සාමාන්‍ය බැවින් ප්‍රතික්ෂේප විය. දිගු, අඩු සාමාන්‍ය මුරපදයක් තෝරන්න. ඔබේ සබැඳිය තවමත් වලංගුයි.",
  "rh.title": "මගේ පෙර සමාගම් සෙවීම්",
  "rh.intro": "ඔබට පමණක් පෞද්ගලිකයි. සෑම සෙවීමක්ම එහි මූලාශ්‍රය සහ වේලාව සමඟ මෙහි සුරැකෙන අතර ඔබට ඕනෑම සටහනක් මැකිය හැක.",
  "rh.empty": "සුරකින ලද සෙවීම් තවම නැත.",
  "rh.line": "ගැළපුණු වාර්තා {matches} ක් · හොඳම ගැළපීම: {match}",
