  "rh.m.weak": "දුර්වල",
  "rh.m.none": "වාර්තාවක් නොමැත",
  "rh.when": "සෙවූ දිනය {date} · මූලාශ්‍රය: {source}",
  "rh.again": "නැවත සොයන්න",
  "rh.delete": "මකන්න",
  "rh.error": "එය සාර්ථක නොවීය. නැවත උත්සාහ කරන්න.",
  "ev.group": "{title} සඳහා තත්ත්වය සහ නිවැරදි කිරීම්",
  "ev.revoked": "ඔබ අවලංගු කළා:",
  "ev.revokedNote": "මෙය ඔබේම සටහනකි. ඔබ මකන තෙක් ගොනුව ගබඩා කර තබයි; කිසිදු සේවා යෝජකයෙකු හෝ සමාලෝචකයෙකු එය තහවුරු කර නැත.",
  "ev.reinstate": "නැවත වලංගු ලෙස සලකුණු කරන්න",
  "ev.revokeSummary": "ඉවත් කළ හෝ ප්‍රතිස්ථාපනය කළ ලෙස සලකුණු කරන්න",
