  "exp.title": "යෝජනාවේ කල් ඉකුත්වීම",
  "exp.none": "කල් ඉකුත්වන දිනයක් නැත. මෙම යෝජනාව තීරණය කරන තෙක් හෝ ප්‍රතිස්ථාපනය කරන තෙක් විවෘතව පවතී.",
  "exp.until": "{date} දක්වා විවෘතයි. ඉන්පසු අලුත් කරන තෙක් එය පිළිගැනීමට හෝ තීරණය කිරීමට නොහැක.",
  "exp.expired": "{date} දින කල් ඉකුත් විය. අලුත් කරන තෙක් එය පිළිගැනීමට හෝ තීරණය කිරීමට නොහැක.",
  "exp.renewed": "වාර {count} ක් අලුත් කළා",
  "exp.askRenew": "එය යෝජනා කළ අයගෙන් එය අලුත් කරන ලෙස ඉල්ලන්න.",
  "exp.date": "කල් ඉකුත්වන දිනය (වසරක් දක්වා)",
