  "err.EMAIL_NOT_CONFIRMED": "ඔබේ ඊමේල් ලිපිනය තවම තහවුරු කර නැත. අප එවූ තහවුරු කිරීමේ ඊමේලය විවෘත කරන්න, නැතහොත් ගිණුම සාදන පිටුවෙන් තවත් එකක් ඉල්ලන්න.",
