  "ce.title": "සාක්ෂි යොමු",
  "ce.intro": "මෙම නඩුව විවෘත කළ පුද්ගලයා ඔවුන්ගේ පෞද්ගලික සුරක්ෂිතාගාරයේ තබා ඇති ලේඛන වෙත යොමු: මාතෘකාව, වර්ගය, ප්‍රමාණය සහ චෙක්සම්. යොමුවක් ඔවුන් සතුව ඇතැයි පවසන දේ පෙන්වයි; එය ගොනුව ලබා නොදේ.",
