  "ce.error": "එය සාර්ථක නොවීය. විවෘත නඩුවක් විවෘත කළ පුද්ගලයාට පමණක් යොමුවක් අමුණන්නට හැක.",
  "adm.chain.title": "විගණන අඛණ්ඩතාව",
  "adm.chain.intro": "සෑම විගණන වාර්තාවක්ම එක් හැෂ් දාමයකට සම්බන්ධ කර ඇත. සත්‍යාපනය සෑම සබැඳියක්ම සහ සෑම වාර්තාවක හැෂ් එකම නැවත ගණනය කර සංස්කරණ, මැකීම් සහ සාමාන්‍ය මාර්ගයෙන් පිටත එක් කළ ඇතුළත් කිරීම් හඳුනා ගනී. දාමය නැංගුරම් ලා තැබීමට ප්‍රධාන හැෂ් එක දත්ත ගබඩාවෙන් පිටත සටහන් කරන්න.",
  "adm.chain.verify": "විගණන දාමය සත්‍යාපනය කරන්න",
