  "dash.recentEmptyTitle": "ඔබේ පළමු දීමනාව මෙතැන් සිට ආරම්භ වේ",
  "dash.recentEmptyBody": "එය අලවන්න, මෙම උපාංගයේ තිර රුවක්, PDF හෝ Word ගොනුවක් කියවන්න, නැතහොත් කොන්දේසි ටයිප් කරන්න. ORYQEN සඳහන් දේ, අතුරුදන් දේ සහ ඇසිය යුතු දේ පෙන්වයි.",
