  "emp.loadError": "රැකියා ඉතිහාසය පූරණය කළ නොහැකි විය. සම්බන්ධ වූ විට නැවත උත්සාහ කරන්න.",
  "emp.checkEntry": "සටහන පරීක්ෂා කරන්න: සේවායෝජකයා, තනතුර සහ ආරම්භ මාසය අවශ්‍යයි; පසුගිය තනතුරකට ආරම්භයට පෙර නොවන අවසාන මාසයක් අවශ්‍යයි.",
