  "export.title": "என் தரவைப் பதிவிறக்கு",
  "export.intro": "உங்கள் சொந்தப் பதிவுகளின் (சுயவிவரம், சலுகைகள், வேலை வரலாறு, வேலைப் பதிவுகள், கடவுச்சீட்டு, டோக்கன் இல்லாத சான்றுகள், பெட்டக ஆவணப் பட்டியல், திட்டம், செயல்பாடு) நகலை இந்தச் சாதனத்தில் கோப்பாகச் சேமிக்கவும். அது எங்கும் பதிவேற்றப்படாது. அதைத் தனிப்பட்டதாக வைத்திருங்கள்.",
  "export.button": "என் தரவுக் கோப்பை உருவாக்கிப் பதிவிறக்கு",
  "export.working": "உங்கள் கோப்பைத் தயாரிக்கிறது…",
  "export.done": "உங்கள் கோப்பு உருவாக்கப்பட்டது. ஒவ்வொரு பிரிவிலும் உள்ள உருப்படிகளின் எண்ணிக்கையைப் பட்டியல் காட்டுகிறது.",
  "export.unavailable": "படிக்க முடியவில்லை",
  "rv.title": "ஆட்சேர்ப்பாளர் சரிபார்ப்பு",
  "rv.intro": "உங்களைத் தொடர்புகொண்டவர் தான் குறிப்பிடும் முதலாளியால் உறுதிப்படுத்தப்பட்டுள்ளாரா எனச் சரிபார்க்கவும். கூற்றை ஆதரிப்பவை, பொருந்தாதவை, சரிபார்க்க முடியாதவை ஆகியவற்றை ORYQEN காட்டுகிறது. பெயர், மின்னஞ்சல் வடிவம் அல்லது சுயவிவரப் பக்கத்தை அது ஒருபோதும் சான்றாகக் கருதாது; யாரேனும் நேர்மையானவரா என்பதையும் அது தீர்மானிக்காது.",
  "rv.yourChecks": "உங்கள் ஆட்சேர்ப்பு சரிபார்ப்புகள்",
  "rv.none": "இதுவரை ஆட்சேர்ப்புச் சரிபார்ப்புகள் இல்லை.",
  "rv.employerConfirms": "முதலாளி உறுதிப்படுத்துகிறார்",
  "rv.employerDisputes": "முதலாளி மறுக்கிறார்",
  "rv.noEmployerAnswer": "முதலாளியின் பதில் இன்னும் இல்லை",
  "rv.open": "முடிவைத் திற",
