  "rv.recruiterName": "உங்களுக்குத் தரப்பட்டபடி ஆட்சேர்ப்பாளரின் பெயர்",
  "rv.employer": "அவர் பிரதிநிதித்துவப்படுத்துவதாகக் கூறும் முதலாளி",
