  "rv.status.conflicting": "முரண்பட்ட சான்றுகள்",
  "rv.asOf": "சான்றுகள் படிக்கப்பட்ட நேரம்",
  "rv.expires": "இந்தச் சரிபார்ப்பு வைக்கப்படும் வரை",
  "rv.why": "இந்த முடிவுக்கான காரணம்",
  "rv.evidence": "சான்றுகள்",
  "rv.unresolved": "இன்னும் தீர்க்கப்படாதவை",
  "rv.wordingTitle": "இந்தச் சாதனத்தில் ஒரு செய்தியின் சொற்களைச் சரிபார்",
  "rv.wordingNote": "நீங்கள் பெற்ற செய்தியை ஒட்டவும். அது இங்கே, உங்கள் சாதனத்திலேயே சரிபார்க்கப்படும்; ORYQEN க்கு அனுப்பப்படாது, சேமிக்கப்படாது.",
  "rv.wordingLabel": "செய்தி உரை",
  "rv.wordingCheck": "சொற்களைச் சரிபார்",
  "rv.wordingNone": "எச்சரிக்கை சொற்கள் எதுவும் கிடைக்கவில்லை. அதற்காகச் செய்தி பாதுகாப்பானது என்று பொருள் அல்ல.",
  "rv.limits": "இந்த முடிவு எதைச் சொல்லும், எதைச் சொல்லாது",
  "rv.again": "மீண்டும் சரிபார்",
