  "rv.confirmDelete": "நீக்குவதை உறுதிப்படுத்து",
  "rv.deleteQuestion": "இந்தச் சரிபார்ப்பையும் அது பற்றிய முதலாளி முடிவுகளையும் அழிக்கவா?",
  "rv.deleteNow": "இப்போது நீக்கு",
  "rv.keep": "வைத்திரு",
  "re.title": "ஆட்சேர்ப்பாளர் உறுதிப்படுத்தல்கள்",
  "re.intro": "கீழுள்ள ஆட்சேர்ப்பாளர்கள் உண்மையில் உங்கள் அமைப்பைப் பிரதிநிதித்துவப்படுத்துகிறார்களா என மக்கள் கேட்டுள்ளனர். அங்கீகாரம் உண்டு என நீங்கள் அறிந்தவர்களை மட்டும் உறுதிப்படுத்துங்கள்; இல்லாதவர்களை மறுக்கவும். உங்கள் முடிவு உங்கள் பெயர், நேரத்துடன் பதிவாகும்; திரும்பப் பெறலாம்; உறுதிப்படுத்தல் காலாவதியாகும். யார் கேட்டார் என்பது உங்களுக்குத் தெரியாது.",
  "re.none": "உங்கள் முடிவுக்காகக் காத்திருக்கும் ஆட்சேர்ப்பாளர் இல்லை.",
  "re.reason": "காரணம் (உங்கள் முடிவுடன் காட்டப்படும்)",
  "re.reasonFirst": "முதலில் ஒரு சிறு காரணத்தை எழுதவும். அது உங்கள் முடிவுடன் காட்டப்படும்.",
  "re.days": "உறுதிப்படுத்தல் செல்லுபடியாகும் நாட்கள் (1–180)",
  "re.confirm": "இந்த நபர் எங்களைப் பிரதிநிதித்துவப்படுத்துகிறார் என உறுதிப்படுத்து",
  "re.dispute": "மறு: இந்த நபருக்கு அங்கீகாரம் இல்லை",
  "re.withdraw": "என் முந்தைய முடிவைத் திரும்பப் பெறு",
  "re.more": "மேலும் காட்டு",
  "re.domainsTitle": "உங்கள் அமைப்பின் டொமைன்களை நிரூபிக்கவும்",
  "re.domainsIntro": "ஆட்சேர்ப்பாளர் மின்னஞ்சல்களும் முதலாளி இணையதளங்களும் அமைப்பு அந்த டொமைனைக் கட்டுப்படுத்துவதைக் காட்டியிருந்தால் மட்டுமே அமைப்புச் சான்றாகக் கருதப்படும். கீழுள்ள வரியை _oryqen-verification.உங்கள்-டொமைன் இல் DNS TXT பதிவாகவோ, https://உங்கள்-டொமைன்/.well-known/oryqen-verification.txt இன் ஒரே உள்ளடக்கமாகவோ வெளியிடவும். ORYQEN ஒவ்வொரு முறையும் சரிபார்க்கும்; முடிவை ஒருபோதும் சேமிக்காது.",
  "re.organization": "அமைப்பு",
  "re.controlSeen": "கட்டுப்பாடு காணப்பட்டது",
  "re.controlNotSeen": "கட்டுப்பாடு இன்னும் காணப்படவில்லை",
  "re.remove": "அகற்று",
  "re.addDomain": "டொமைனைச் சேர் (அதிகபட்சம் 5)",
