  "ag.create.summary": "பதிப்புடைய ஒப்பந்தத்தை உருவாக்கு",
  "ag.create.intro": "இந்தச் சேமித்த சலுகையை வெளிப்படையான ஒப்புதல்கள், சுயாதீன உறுதிப்படுத்தலுடன் முடக்கவும். ஏற்கனவே உள்ள உறுதிப்படுத்தல்கள் தனியாகவே இருக்கும்.",
  "ag.create.rep": "நியமிக்கப்பட்ட பிரதிநிதி அடையாளம்",
  "ag.create.repNote": "ஒப்புக்கொண்ட பங்கேற்பாளரின் கணக்கு அடையாளத்தைப் பயன்படுத்தவும். சேவையகம் தற்போதைய நிறுவன அதிகாரத்தைச் சரிபார்க்கும்; அடையாளம் அணுகல் வழங்காது.",
  "ag.create.saving": "வரைவைச் சேமிக்கிறது…",
  "ag.create.button": "பாதுகாப்பான வரைவை உருவாக்கு",
  "ag.create.error": "பிரதிநிதி அடையாளத்தைச் சரிபார்த்து மீண்டும் முயலவும். எந்த ஒப்பந்தமும் சேமிக்கப்பட்டதாகக் கருதப்படவில்லை.",
  "ag.st.ready_for_review": "மதிப்பாய்வுக்குத் தயார்",
