  "ag.st.awaiting_confirmations": "உறுதிப்படுத்தல்களுக்காகக் காத்திருக்கிறது",
  "ag.st.effective": "இரு பங்கேற்பாளர்களும் உறுதிப்படுத்தினர்",
  "ag.st.declined": "இந்தப் பதிப்பு நிராகரிக்கப்பட்டது",
  "ag.st.superseded": "மாற்றப்பட்ட பதிப்பு",
  "ag.st.revision_conflict": "மூலம் அல்லது அதிகாரம் மாறியது — புதிய பதிப்பு தேவை",
  "ag.loadError": "ஒப்பந்தத்தைச் சரிபார்க்க முடியவில்லை.",
  "ag.actionError": "செயலைச் சரிபார்க்க முடியவில்லை. காட்டப்பட்ட அதே பதிப்புடன் மீண்டும் முயலவும்.",
  "ag.title": "ஒப்பந்தச் சுருக்கம்",
  "ag.subtitle": "சேமித்த ஒரு பதிப்பின் சுயாதீன மதிப்பாய்வு.",
  "ag.notSignature": "உறுதிப்படுத்தல்கள் ORYQEN இல் ஒவ்வொரு பங்கேற்பாளரின் மதிப்பாய்வைப் பதிவு செய்கின்றன. அவை குறியாக்க கையொப்பங்களோ சட்டப்படி நிறைவேற்றப்பட்ட ஒப்பந்தத்தின் சான்றோ அல்ல.",
