  "wa.pick": "இணைக்க ஒரு ஆவணத்தைத் தேர்ந்தெடு",
  "wa.attach": "ஆவணத்தை இணை",
  "wa.detach": "இணைப்பை நீக்கு",
  "wa.noVault": "உங்கள் சான்று பெட்டகம் காலியாக உள்ளது. முதலில் அதில் ஆவணத்தைச் சேமிக்கவும்.",
  "wa.error": "அது செயல்படவில்லை. மீண்டும் முயலவும்.",
  "im.reading": "இந்தச் சாதனத்தில் படிக்கிறது…",
  "im.review": "பிரித்தெடுத்த உரையை மதிப்பாய்வு செய்",
  "im.removePersonal": "தேவையில்லாத தனிப்பட்ட விவரங்களை நீக்கவும். தொடர்வது உரை வரைவை மட்டுமே நிரப்பும்; விதிமுறைகளைச் சேமிப்பதும் விருப்ப AI ஒப்புதலும் தனிச் செயல்கள்.",
  "im.shot.aria": "உள்ளூர் திரைப்பட வாசிப்பான்",
  "im.shot.title": "இந்தச் சாதனத்தில் திரைப்படத்தைப் படி",
  "im.shot.intro": "அச்சிட்ட ஆங்கில உரை மட்டும். உங்கள் படம் இந்தச் சாதனத்திலேயே இருக்கும்; சேமிக்கவோ பதிவேற்றவோ படாது. உரை அடையாளம் தவறக்கூடும்; தொடரும் முன் மதிப்பாய்வு செய்யவும். இது OCR, நேரடி AI பகுப்பாய்வு அல்ல.",
  "im.shot.file": "சலுகைத் திரைப்படம்",
  "im.shot.cancel": "படிப்பதை ரத்துசெய்",
  "im.shot.use": "மதிப்பாய்வு செய்த உரையைப் பயன்படுத்து",
  "im.shot.timeout": "படிப்பது நேரம் முடிந்தது. சிறிய படத்தை முயலவும் அல்லது விதிமுறைகளைக் கையால் உள்ளிடவும்.",
  "im.shot.badFile": "5 MB க்குக் குறைவான PNG அல்லது JPEG திரைப்படத்தைத் தேர்ந்தெடுக்கவும். PDF, SVG ஆதரிக்கப்படாது.",
  "im.shot.tooBig": "12 மெகாபிக்சலுக்கு மிகாத படத்தைத் தேர்ந்தெடுக்கவும்.",
  "im.shot.unavailable": "உள்ளூர் பட வாசிப்பான் கிடைக்கவில்லை. மீண்டும் முயலவும் அல்லது விதிமுறைகளைக் கையால் உள்ளிடவும்.",
  "im.shot.noText": "உரையைப் படிக்க முடியவில்லை. தெளிவான ஆங்கிலத் திரைப்படத்தை முயலவும் அல்லது விதிமுறைகளைக் கையால் உள்ளிடவும்.",
