  "im.pdf.aria": "உள்ளூர் PDF வாசிப்பான்",
  "im.pdf.title": "இந்தச் சாதனத்தில் உரை PDF ஐப் படி",
  "im.pdf.intro": "உங்கள் PDF இந்தச் சாதனத்திலேயே இருக்கும்; சேமிக்கவோ பதிவேற்றவோ படாது. உரை அடிப்படையிலான PDF மட்டுமே செயல்படும் (5 MB வரை, {pages} பக்கங்கள்); ஸ்கேன் செய்த PDF க்கு திரைப்பட வாசிப்பான் தேவை. பிரித்தெடுத்த உரை முழுமையற்றதாகவோ வரிசை தவறியதாகவோ இருக்கலாம்; தொடரும் முன் மதிப்பாய்வு செய்யவும். இது உரைப் பிரித்தெடுப்பு, AI பகுப்பாய்வு அல்ல.",
