  "ev.intro": "UTF-8 .txt கோப்பை உள்ளூரில் படித்து, அதன் பகுதிகளை மதிப்பாய்வு செய்யவும். தனிப்பட்ட பணி வரைவைச் சேமிக்கும் வரை எதுவும் அனுப்பப்படாது. மூலக் கோப்பு பதிவேற்றப்படவோ வைக்கப்படவோ மாட்டாது; இறக்குமதி செய்த உரை சுயாதீனமாகச் சரிபார்க்கப்படவில்லை.",
  "ev.file": "உரை ஆவணம்",
