  "au.reg.employerSub": "ஓர் அமைப்பைப் பிரதிநிதித்துவப்படுத்தி வேலை விதிமுறைகளைத் தெளிவுபடுத்துங்கள்.",
  "au.reg.employerNote": "முதலாளி அதிகாரத்துக்குத் தனியாக மதிப்பாய்வு செய்யப்பட்ட நிறுவன உறுப்பினர் தகுதி தேவை. கணக்கைத் தேர்ந்தெடுப்பது ஒப்புதல் வழங்காது.",
  "au.reg.checkInbox": "உங்கள் இன்பாக்ஸைப் பார்க்கவும்",
  "au.reg.sentStatus": "இந்த முகவரிக்குப் பதிவு கிடைக்குமானால், உறுதிப்படுத்தும் இணைப்புக்காக உங்கள் மின்னஞ்சலைப் பார்க்கவும். ஏற்கனவே உள்ள கணக்குகள் உள்நுழையலாம்.",
  "au.reg.sentNext": "இணைப்பைத் திறந்து, மின்னஞ்சலை உறுதிப்படுத்தி, சுயவிவரத்தை முடிக்கவும். வரவில்லை எனில் ஸ்பேமைப் பார்க்கவும்.",
  "au.reg.checkingLink": "உங்கள் இணைப்பைச் சரிபார்க்கிறது…",
  "au.reg.openEmail": "உங்கள் சரிபார்ப்பு மின்னஞ்சலைத் திறக்கவும்",
  "au.reg.linkExpired": "இந்த இணைப்பு காலாவதியாகிவிட்டது",
  "au.reg.linkUnusable": "இந்த இணைப்பைப் பயன்படுத்த முடியாது",
  "au.reg.waitFormat": "இணைப்பின் வடிவத்தைச் சரிபார்க்கும் வரை காத்திருக்கவும்.",
  "au.reg.useLatest": "உங்கள் இன்பாக்ஸில் உள்ள சமீபத்திய உறுதிப்படுத்தல் இணைப்பைப் பயன்படுத்தவும். அது இல்லை அல்லது வேலை செய்யவில்லை எனில், கீழே புதிய மின்னஞ்சலைக் கோரவும். ஏற்கனவே உறுதிப்படுத்திவிட்டீர்களா? தொடர உள்நுழையவும்.",
  "au.reg.accountType": "{kind} கணக்கு",
  "au.reg.kindEmployer": "முதலாளி",
  "au.reg.kindWorker": "பணியாளர்",
  "au.reg.change": "மாற்று",
  "au.reg.yourName": "உங்கள் பெயர்",
  "au.reg.confirmPassword": "கடவுச்சொல்லை உறுதிப்படுத்து",
  "au.reg.passwordHelp": "12–128 எழுத்துகளைப் பயன்படுத்தவும். நீண்ட, தனித்துவமான கடவுச்சொற்றொடர் நன்றாக வேலை செய்யும்.",
  "au.reg.confirmSession": "உங்கள் மின்னஞ்சல் இணைப்பு Supabase இலிருந்து திரும்பியுள்ளது. உங்கள் அமர்வைச் சரிபார்த்து தனிப்பட்ட சுயவிவரத்தை அமைக்கத் தொடரவும்.",
  "au.reg.confirmEmailTo": "உங்கள் தனிப்பட்ட சுயவிவரத்துக்குச் செல்ல மின்னஞ்சலை உறுதிப்படுத்தவும்.",
  "au.reg.onlyIfRequested": "இந்தக் கணக்கை நீங்கள் கோரியிருந்தால் மட்டுமே தொடரவும்.",
  "au.reg.profileIntro": "பணிப் பங்கேற்பாளர்களுக்கு உங்கள் பெயர் எவ்வாறு தோன்றும் என்பதைத் தேர்ந்தெடுக்கவும். அமைப்புகளில் மாற்றலாம்.",
