  "pp.downloadNote": "பதிவிறக்கங்கள் ஒவ்வொரு பக்கத்தையும் மீண்டும் சரிபார்க்கும், 1,000 தகுதியான பதிவுகள் வரை. பக்கங்கள் படிக்கப்படும்போது தகுதி மாறலாம். இந்தக் கோப்பு கையொப்பமிட்ட சான்றிதழோ நேரடிச் சரிபார்ப்பு இணைப்போ அல்ல. இதைத் தொலைவிலிருந்து ரத்து செய்யவோ புதுப்பிக்கவோ முடியாது. தனிப்பட்டதாக வைத்திருங்கள்.",
