  "pv.intro": "அணுகல், திருத்தம், செயலிழப்பு, நீக்கக் கோரிக்கைகளுக்குக் கைமுறை மதிப்பாய்வு தேவை. கோரிக்கை சமர்ப்பிப்பது தரவை ஏற்றுமதி செய்யாது, உங்கள் கணக்கை செயலிழக்கச் செய்யாது, பதிவுகளை அழிக்காது. தணிக்கை மற்றும் பகிர்ந்த பதிவுத் தக்கவைப்பு தனியாக மதிப்பாய்வு செய்யப்பட வேண்டும்.",
  "pv.operatorNote": "மதிப்பாய்வுக்கு உங்களுக்கு ஒதுக்கப்பட்ட தனியுரிமைத் திறனும் சரிபார்க்கப்பட்ட அங்கீகாரி அமர்வும் மட்டுமே அனுமதிக்கும். அங்கீகரிக்கப்பட்ட கைமுறை நடைமுறை முடியும் வரை நிறைவேற்றப்பட்டதாகக் குறிக்க வேண்டாம். உணர்திறன் அற்ற உள் குறிப்பைப் பதிவு செய்யவும்; ஏற்றுமதி செய்த தரவையோ பதிவிறக்க இணைப்பையோ ஒருபோதும் அல்ல.",
  "pv.kind": "தனியுரிமைக் கோரிக்கை வகை",
  "pv.k.access": "என் தகவலுக்கான அணுகல்",
  "pv.k.correction": "என் தகவலைத் திருத்து",
  "pv.k.deactivation": "கணக்குச் செயலிழப்பைக் கோரு",
  "pv.k.deletion": "நீக்க மதிப்பாய்வைக் கோரு",
  "pv.scope": "கோரிக்கையின் நோக்கம்",
  "pv.scopeNote": "பதிவுகள் அல்லது சிக்கலைச் சுருக்கமாக விவரிக்கவும். கடவுச்சொற்கள், அடையாள ஆவணங்கள், முக்கிய வேலை விவரங்களைச் சேர்க்க வேண்டாம். உங்கள் கோரிக்கை உங்களுக்கும் அங்கீகரிக்கப்பட்ட தனியுரிமை மதிப்பாய்வாளர்களுக்கும் தெரியும்.",
