  "sec.deactivatedAll": "உங்கள் ORYQEN கணக்கு செயலிழக்கப்பட்டது; அனைத்துப் புதுப்பிப்பு அமர்வுகளும் வெளியேற்றப்பட்டன.",
  "sec.deactivatedPartial": "உங்கள் ORYQEN கணக்கு செயலிழக்கப்பட்டது. அங்கீகார அமர்வு ரத்தை உறுதிப்படுத்த முடியவில்லை, ஆனால் பயன்பாட்டு அணுகல் தடுக்கப்பட்டுள்ளது.",
  "sec.aria": "கணக்குப் பாதுகாப்பு",
  "sec.title": "அங்கீகாரியும் கணக்கு அணுகலும்",
  "sec.doneNote": "இருக்கும் ஒப்பந்தங்கள், வேலை வரலாறு, தணிக்கைப் பதிவுகள் வைக்கப்படும். இது நீக்கம் அல்ல. சுய-சேவை மீள்செயலாக்கம் கிடைக்காது.",
  "sec.returnSignIn": "உள்நுழைவுக்குத் திரும்பு",
  "sec.intro": "முக்கியமான கணக்குச் செயல்களுக்கு அங்கீகாரி செயலியைப் பயன்படுத்தவும். இது SMS அனுப்பாது, முதலாளி/மதிப்பாய்வாளர் அனுமதிகளை வழங்காது.",
  "sec.loading": "கணக்குப் பாதுகாப்பை ஏற்றுகிறது…",
  "sec.setup": "கணக்கு அங்கீகாரியை அமை",
  "sec.setupKey": "இந்தத் தனிப்பட்ட அமைவு விசையை உங்கள் அங்கீகாரி செயலியில் சேர்க்கவும். இது பதிவின்போது மட்டுமே காட்டப்படும்; பகிர வேண்டாம்.",
  "sec.code": "கணக்கு அங்கீகாரி குறியீடு",
  "sec.verify": "கணக்கு அங்கீகாரியைச் சரிபார்",
  "sec.deactSummary": "என் கணக்கைச் செயலிழக்கச் செய்",
  "sec.deactNote": "செயலிழப்பு உங்கள் ORYQEN அணுகலையும் பகிர்ந்த கடவுச்சீட்டுக்கான பெறுபவர் அணுகலையும் தடுக்கும். முன்பு பதிவிறக்கிய நகல்களைத் திரும்பப் பெற முடியாது. ஒப்பந்தங்களும் தணிக்கை வரலாறும் வைக்கப்படும்; செயலிழப்பு தரவை அழிக்காது, வரலாற்று உறுதிப்படுத்தல்களை மீட்டுக்கொள்ளாது. சுய-சேவை மீள்செயலாக்கம் கிடைக்காது. நீக்க மதிப்பாய்வுக்குச் செயலிழக்கும் முன் தனியுரிமைக் கோரிக்கைகளைப் பயன்படுத்தவும்.",
