  "oc.error": "ஒப்பீடு கிடைக்கவில்லை. இந்தச் சலுகைகளில் ஒன்றை இனி அணுக முடியாமல் இருக்கலாம். இணைப்பைச் சரிபார்க்கவும் அல்லது வேறு சலுகைகளைத் தேர்ந்தெடுக்கவும்.",
  "oc.aria": "சலுகை ஒப்பீடு",
  "oc.title": "சேமித்த விதிமுறைகளை ஒப்பிடு",
  "oc.intro": "இவை இப்போது ஏற்றப்பட்ட சேமித்த திருத்தங்கள். தொகைகள் பதிவானபடியே காட்டப்படும்: நாணயங்கள், ஊதியக் காலங்கள், மொத்த/நிகர அடிப்படை வேறுபடலாம். இந்த ஒப்பீடு முதலாளிகளைத் தரவரிசைப்படுத்தாது, அவர்களின் கூற்றுகளைச் சரிபார்க்காது.",
