  "oh.intro": "படிக்க மட்டும் முடியும் சேமித்த விதிமுறைகள். வரலாற்றுத் திருத்தங்கள் தற்போதைய ஒப்பந்த உறுதிப்படுத்தலோ சரிபார்ப்போ அல்ல.",
