  "oh.revAria": "சேமித்த திருத்தம் {version}",
  "oh.rev": "திருத்தம் {version}",
  "oh.changes": "இந்தத் திருத்தத்தில் மாற்றங்கள்",
  "oh.none": "முந்தைய அணுகக்கூடிய திருத்தங்கள் இல்லை.",
  "oh.reload": "சமீபத்திய வரலாற்றை மீண்டும் ஏற்று",
  "oh.earlier": "முந்தைய திருத்தங்கள்",
  "cf.unavailable": "கடிதப் போக்குவரத்து கிடைக்கவில்லை.",
  "cf.appealSaved": "மேல்முறையீடு புதிய இணைக்கப்பட்ட வழக்காகச் சேமிக்கப்பட்டது. வேறொரு சுயாதீன மதிப்பாய்வாளர் நியமிக்கப்பட வேண்டும்.",
  "cf.responseSaved": "பதில் மாற்ற முடியாத வழக்குக் கடிதப் போக்குவரத்தில் சேமிக்கப்பட்டது.",
  "cf.saveFail": "கடிதப் போக்குவரத்தைச் சேமிக்க முடியவில்லை.",
  "cf.aria": "வழக்குக் கடிதப் போக்குவரத்து",
  "cf.title": "பதில்களும் மேல்முறையீடுகளும்",
  "cf.loading": "கடிதப் போக்குவரத்தை ஏற்றுகிறது…",
  "cf.openLinked": "இணைக்கப்பட்ட மேல்முறையீட்டு வழக்கைத் திற",
  "cf.none": "பதில்கள் அல்லது மேல்முறையீடுகள் பதிவு செய்யப்படவில்லை.",
  "cf.grounds": "மேல்முறையீட்டு காரணங்கள்",
  "cf.response": "பதில்",
  "cf.visibility": "அங்கீகரிக்கப்பட்ட பங்கேற்பாளர்களுக்கும் ஏற்றுக்கொண்ட சுயாதீன மதிப்பாய்வாளருக்கும் மட்டுமே தெரியும். தேவையான விவரங்களை மட்டும் சேர்க்கவும்.",
  "cf.appealNote": "மேல்முறையீடு தற்போதைய சமர்ப்பித்த திருத்தத்துக்கு எதிராகப் புதிய வழக்கைத் திறக்கும். அது அசல் முடிவையும் அனைத்துக் கடவுச்சீட்டு விலக்குகளையும் பாதுகாக்கும். திரும்பப் பெற்ற அல்லது வரைவுப் பதிவுகள் முதலில் திருத்தச் செயல்முறையைப் பின்பற்ற வேண்டும்.",
  "cf.submitAppeal": "மேல்முறையீட்டைச் சமர்ப்பித்து மதிப்பாய்வை மீண்டும் திற",
  "cf.saveResponse": "பதிலைச் சேமி",
  "cf.next": "அடுத்த கடிதப் போக்குவரத்துப் பக்கம்",
  "cf.reload": "கடிதப் போக்குவரத்தை மீண்டும் ஏற்று",
  "nf.loadError": "செயல்பாட்டை ஏற்ற முடியவில்லை. உள்நுழைந்து இணைந்த பின் மீண்டும் முயலவும்.",
  "nf.readFail": "படித்த நிலையைச் சேமிக்க முடியவில்லை. அணுகலைச் சரிபார்க்க மீண்டும் ஏற்றவும்.",
  "nf.aria": "கணக்கு அறிவிப்புகள்",
  "nf.subtitle": "சலுகை, ஒப்பந்தம், வேலை, அமைப்புச் செயல்பாடு",
  "nf.intro": "பயன்பாட்டிற்குள் செயல்பாடு மட்டும். மின்னஞ்சல், புஷ் விநியோகம் இணைக்கப்படவில்லை. வரலாற்று ஒப்புதல் அறிவிப்புகள் தற்போதைய அதிகாரத்தை நிறுவாது. தற்போதைய நிலைக்குத் தொடர்புடைய பதிவைத் திறக்கவும்.",
  "nf.prefs": "அறிவிப்பு விருப்பங்கள் (இந்தச் சாதனம்)",
  "nf.prefsNote": "இந்த ஊட்டம் இந்தச் சாதனத்தில் எந்த வகைச் செயல்பாடுகளைக் காட்டும் என்பதைத் தேர்ந்தெடுக்கவும். மறைக்கப்பட்ட செயல்பாடு இன்னும் பதிவாகும்; ஒருபோதும் நீக்கப்படாது. வழக்குப் பதில்களும் மேல்முறையீடுகளும் மறைக்கப்பட முடியாது, ஏனெனில் ஒன்றைத் தவறவிட்டால் கெடு தவறலாம்.",
  "nf.c.offers": "சலுகைத் திருத்தங்கள்",
  "nf.c.agreements": "ஒப்பந்த முடிவுகள்",
  "nf.c.work": "பணிப் பதிவு முடிவுகளும் ஒருமைப்பாட்டு நிகழ்வுகளும்",
  "nf.c.organization": "அமைப்பு முடிவுகள்",
  "nf.c.cases": "வழக்குப் பதில்களும் மேல்முறையீடுகளும்",
  "nf.loading": "செயல்பாட்டை ஏற்றுகிறது…",
  "nf.none": "அணுகக்கூடிய செயல்பாடு இன்னும் இல்லை.",
  "nf.hiddenOne": "உங்கள் விருப்பங்களால் 1 உருப்படி மறைக்கப்பட்டது.",
  "nf.hiddenMany": "உங்கள் விருப்பங்களால் {count} உருப்படிகள் மறைக்கப்பட்டன.",
