  "gd.aria": "தனிப்பட்ட வழிகாட்டுதல்",
  "gd.notice": "நேரடி AI வழிகாட்டுதல் கிடைக்கவில்லை. இது விதி அடிப்படையிலான தயாரிப்பு வழிகாட்டி; AI உருவாக்கிய பதிலோ சட்ட ஆலோசனையோ அல்ல. இது உங்கள் கேள்வியைப் பதிவு செய்து நீங்கள் தேர்ந்த தலைப்புக்குப் பொது வழிகாட்டுதலை வழங்கும்; தன்னிச்சையான கேள்விகளை விளக்காது, செயல்களைச் செய்யாது.",
  "gd.privacy": "இந்த வரலாற்றை நீங்கள் மட்டுமே அணுக முடியும். கடவுச்சொற்கள், அடையாள எண்கள் அல்லது தேவையற்ற தனிப்பட்ட விவரங்களைச் சேர்க்க வேண்டாம்.",
