  "gd.limit": "இந்த உரையாடல் 100 செய்திகளை எட்டியுள்ளது. தொடர புதிய உரையாடலைத் தொடங்கவும்.",
  "rp.summary": "இதைப் பற்றிய சிக்கலைப் புகாரளி",
  "rp.intro": "புகார்கள் தனிப்பட்ட முறையில் ORYQEN மதிப்பாய்வாளர்களுக்குச் செல்லும். நீங்கள் குறிப்பிடும் நபர் அல்லது அமைப்புக்கு அவை ஒருபோதும் காட்டப்படாது; ஒரு புகாரின் அடிப்படையில் ORYQEN யாரையும் குற்றம்சாட்டாது. கடவுச்சொற்கள், அடையாள எண்கள், ஆவணங்களைச் சேர்க்க வேண்டாம்.",
