  "rp.sent": "புகார் அனுப்பப்பட்டது. அமைப்புகளில் என் புகார்கள் பகுதியில் அதைப் பின்தொடரலாம்; திறந்திருக்கும்போது திரும்பப் பெறலாம்.",
