  "adm.rangeNote": "நிகழ்வு தேதிகள் UTC ஐப் பயன்படுத்தும்; அதிகபட்ச வரம்பு 92 நாட்கள். நபர், நிறுவனம், அணுகல், அமைப்புகள் பட்டியல்களில் பழைய பதிவுகளும் உள்ளன. மொத்தங்கள் பதிவான முழுக் காலத்தையும் குறிக்கும்; போக்குகள் தேதி வடிகட்டியைப் பின்பற்றும்.",
  "adm.unavailableTitle": "பதிவுகள் கிடைக்கவில்லை",
  "adm.unavailableBody": "உங்கள் தற்போதைய அமர்வையும் நியமனத்தையும் சரிபார்க்கப் புதுப்பிக்கவும். முன்பு காட்டிய தரவு அழிக்கப்பட்டது.",
