  "im.docx.aria": "உள்ளூர் Word வாசிப்பான்",
  "im.docx.title": "இந்தச் சாதனத்தில் Word ஆவணத்தைப் படிக்கவும்",
  "im.docx.intro": "உங்கள் .docx கோப்பு இந்தச் சாதனத்திலேயே இருக்கும்; சேமிக்கப்படாது, பதிவேற்றப்படாது. 5 MB வரை முதன்மை உரை மட்டுமே படிக்கப்படும். பிரித்தெடுத்த உரை முழுமையற்றதாக அல்லது வரிசை மாறியதாக இருக்கலாம், எனவே தொடரும் முன் சரிபார்க்கவும்.",
  "im.docx.file": "சலுகை Word ஆவணம் (.docx)",
  "im.docx.truncated": "முதல் {chars} எழுத்துகள் மட்டும் வைக்கப்படும்.",
  "im.docx.e.type": "அந்தக் கோப்பு .docx ஆவணம் அல்ல. .docx கோப்பைத் தேர்ந்தெடுக்கவும் அல்லது உரையை ஒட்டவும்.",
  "im.docx.e.size": "5 MB க்கும் குறைவான Word ஆவணத்தைத் தேர்ந்தெடுக்கவும்.",
  "im.docx.e.legacy": "பழைய .doc கோப்புகள் ஆதரிக்கப்படவில்லை. கோப்பை .docx ஆகச் சேமிக்கவும் அல்லது உரையை ஒட்டவும்.",
  "im.docx.e.unreadable": "இந்த ஆவணத்தைப் படிக்க முடியவில்லை. வேறு கோப்பை முயலவும் அல்லது உரையை ஒட்டவும்.",
  "im.docx.e.too_large": "இந்த ஆவணம் இங்கே படிக்க மிகப் பெரியது. உங்களுக்குத் தேவையான பகுதியை ஒட்டவும்.",
  "im.docx.e.no_text": "இந்த ஆவணத்தில் உரை எதுவும் இல்லை. அதற்குப் பதிலாக உரையை ஒட்டவும்.",
  "opc.title": "சேமித்த பட்டியல்களை ஒப்பிடு",
  "opc.intro": "ஒவ்வொன்றும் குறிப்பிடுவதை அருகருகே காண உங்கள் சேமித்த பட்டியல்களில் {max} வரை தேர்ந்தெடுக்கவும். எதுவும் தரவரிசைப்படுத்தப்படாது, எதுவும் சேமிக்கப்படாது.",
  "opc.pick": "ஒப்பிட வேண்டிய பட்டியல்கள்",
  "opc.needTwo": "குறைந்தது இரண்டு பட்டியல்களைத் தேர்ந்தெடுக்கவும்.",
  "opc.caption": "தேர்ந்தெடுத்த பட்டியல்கள் ஒப்பிடப்பட்டன",
  "opc.field": "விவரம்",
  "opc.differs": "வேறுபடுகிறது",
  "opc.payNote": "இந்தப் பட்டியல்கள் சம்பளத்தை வெவ்வேறு நாணயங்களில் அல்லது காலங்களில் குறிப்பிடுகின்றன. சம்பளம் குறிப்பிட்டபடியே காட்டப்படுகிறது, மாற்றப்படவில்லை, எனவே நேரடியாக ஒப்பிட முடியாது.",
