  "au.rec.checkingLink": "உங்கள் இணைப்பைச் சரிபார்க்கிறது…",
  "au.rec.waitFormat": "இணைப்பின் வடிவத்தைச் சரிபார்க்கும் வரை காத்திருக்கவும்.",
  "au.rec.openEmail": "உங்கள் மின்னஞ்சலில் உள்ள இணைப்பைத் திறக்கவும்",
  "au.rec.linkExpired": "இந்த இணைப்பு காலாவதியாகிவிட்டது",
  "au.rec.linkUnusable": "இந்த இணைப்பைப் பயன்படுத்த முடியாது",
  "au.rec.linkUnsupported": "இந்த இணைப்பை இங்கே முடிக்க முடியாது",
  "au.rec.unsupportedBody": "இந்த மின்னஞ்சல் இணைப்பு வேறொரு உள்நுழைவு முறைக்காக உருவாக்கப்பட்டது. புதிய கடவுச்சொல் மீட்டமைப்பு மின்னஞ்சலைக் கோரி, புதியதைத் திறக்கவும்.",
  "au.rec.useLatest": "நாங்கள் அனுப்பிய புதிய மின்னஞ்சலைப் பயன்படுத்தவும், அல்லது புதியதைக் கோரவும். ஒரு இணைப்பு ஒரு முறை மட்டும், குறிப்பிட்ட நேரத்துக்கு மட்டும் வேலை செய்யும்.",
  "au.rec.requestNew": "புதிய மீட்டமைப்பு மின்னஞ்சலைக் கோரு",
  "au.rec.linkUsedError": "இந்த மீட்டமைப்பு இணைப்பு செல்லாதது, காலாவதியானது அல்லது ஏற்கனவே பயன்படுத்தப்பட்டது. புதியதைக் கோரவும்.",
  "au.rec.inviteNote": "நீங்கள் ORYQEN க்கு அழைக்கப்பட்டுள்ளீர்கள். உங்கள் கடவுச்சொல்லைத் தேர்ந்தெடுக்கத் தொடரவும். இந்தப் பக்கத்தைத் திறப்பதால் மட்டும் உங்கள் அழைப்பு பயன்படுத்தப்படாது.",
  "au.rec.samePassword": "உங்கள் தற்போதைய கடவுச்சொல்லிலிருந்து வேறுபட்ட கடவுச்சொல்லைத் தேர்ந்தெடுக்கவும். உங்கள் இணைப்பு இன்னும் செல்லுபடியாகும்.",
  "au.rec.weakPassword": "அந்தக் கடவுச்சொல் ஊகிக்க எளிதானது அல்லது மிகவும் பொதுவானது என்பதால் நிராகரிக்கப்பட்டது. நீளமான, குறைவாகப் பொதுவான கடவுச்சொல்லைத் தேர்ந்தெடுக்கவும். உங்கள் இணைப்பு இன்னும் செல்லுபடியாகும்.",
  "rh.title": "என் முந்தைய நிறுவனத் தேடல்கள்",
  "rh.intro": "உங்களுக்கு மட்டும் தனிப்பட்டது. ஒவ்வொரு தேடலும் அதன் ஆதாரம் மற்றும் நேரத்துடன் இங்கே சேமிக்கப்படும்; எந்த உள்ளீட்டையும் நீக்கலாம்.",
