  "err.AGREEMENT_EXPIRED": "இந்த ஒப்பந்த முன்மொழிவு காலாவதியாகிவிட்டது. இதை முன்மொழிந்தவர் பிந்தைய காலாவதி தேதியை அமைத்துப் புதுப்பிக்கலாம்.",
  "err.EVIDENCE_REVOKED": "இந்த ஆவணம் திரும்பப் பெற்றதாகக் குறிக்கப்பட்டுள்ளது. இணைக்கும் முன் உங்கள் சான்று பெட்டகத்தில் மீண்டும் செல்லுபடியாக குறிக்கவும்.",
  "err.INVALID_CREDENTIALS": "அந்த மின்னஞ்சலும் கடவுச்சொல்லும் பொருந்தவில்லை. சரிபார்க்கவும் அல்லது புதியதை அமைக்க 'கடவுச்சொல் மறந்துவிட்டதா' பயன்படுத்தவும்.",
  "err.EMAIL_NOT_CONFIRMED": "உங்கள் மின்னஞ்சல் முகவரி இன்னும் உறுதிப்படுத்தப்படவில்லை. நாங்கள் அனுப்பிய உறுதிப்படுத்தல் மின்னஞ்சலைத் திறக்கவும் அல்லது கணக்கு உருவாக்கும் பக்கத்தில் மற்றொன்றைக் கோரவும்.",
  "err.MFA_REQUIRED": "தொடர உங்கள் அங்கீகார குறியீட்டைச் சரிபார்க்கவும்.",
  "err.ACTION_FORBIDDEN": "இந்த செயல் கிடைக்கவில்லை.",
  "err.WRONG_ORIGIN": "இது இந்த ORYQEN சூழலின் அதிகாரப்பூர்வ முகவரி அல்ல, எனவே இங்கு உள்நுழைவதும் சேமிப்பதும் தடுக்கப்பட்டுள்ளது. அதிகாரப்பூர்வ முகவரியைத் திறந்து மீண்டும் முயலவும்.",
  "err.WEAK_PASSWORD": "அந்தக் கடவுச்சொல் எளிதில் ஊகிக்கக்கூடியது அல்லது மிகவும் பொதுவானது என நிராகரிக்கப்பட்டது. நீளமான, குறைவாகப் பயன்படுத்தப்படும் கடவுச்சொல்லைத் தேர்வுசெய்யவும்.",
