  "err.RESET_EXPIRED": "உங்கள் கடவுச்சொல் மீட்டமைப்பு அமர்வு காலாவதியாகிவிட்டது. புதிய மீட்டமைப்பு மின்னஞ்சலைக் கோரவும்.",
  "err.NOT_FOUND": "கோரிய பதிவு கிடைக்கவில்லை.",
