  "ce.title": "சான்று குறிப்புகள்",
  "ce.intro": "இந்த வழக்கைத் திறந்தவர் தங்கள் தனிப்பட்ட பெட்டகத்தில் வைத்துள்ள ஆவணங்களுக்கான குறிப்புகள்: தலைப்பு, வகை, அளவு மற்றும் சரிபார்ப்புத் தொகை. ஒரு குறிப்பு அவர்களிடம் உள்ளதாகக் கூறுவதைக் காட்டும்; கோப்பை ஒப்படைக்காது.",
