  "ai.name.fallback": "der Anbieter",
  "ai.statePausedOne": "{name} ist für etwa 1 Minute pausiert",
  "ai.statePausedMany": "{name} ist für etwa {n} Minuten pausiert",
  "ai.statePaused": "{name} ist pausiert",
  "ai.stateOver": "{name} hat sein Nutzungsbudget überschritten",
  "ai.pauseNote": "Solange ein Anbieter pausiert ist, wird nichts an ihn gesendet. Lokale Regeln und manuelle Prüfung bleiben verfügbar.",
  "ai.sendIntro": "Senden Sie den geprüften Text unten zur beratenden Analyse an {provider} ({model}). Entfernen Sie zuvor Namen, Kontaktdaten, Kennnummern und vertrauliche Bedingungen.",
  "ai.redactNote": "Die automatische Schwärzung entfernt einige erkennbare Kennungen. Sie kann Anonymität nicht garantieren. Prüfen Sie die gesamte Vorschau, bevor Sie einwilligen.",
  "ai.textLabel": "Text, der gesendet wird",
  "ai.region": "Vom Betreiber angegebene Verarbeitungsregion: {region}. Datennutzung und Aufbewahrung: {use}",
  "ai.noRecall": "Einmal gesendete Daten können vom Anbieter nicht zurückgeholt werden. Jede Anfrage braucht eine neue Einwilligung; bei geändertem Text oder geänderter Anbieterrichtlinie ist erneut einzuwilligen.",
  "ai.mayBeWrong": "Die Antwort kann falsch sein. Sie kann kein Unternehmen bestätigen, keine Rechtskonformität feststellen und keine Vereinbarung bekräftigen. Ein minimaler Berechtigungsbeleg wird ohne den Angebotstext aufbewahrt. Ein erneuter Versuch verbraucht eine weitere begrenzte Anfrage.",
