  "pv.intro": "Anfragen zu Auskunft, Berichtigung, Deaktivierung und Löschung erfordern eine manuelle Prüfung. Das Einreichen exportiert keine Daten, deaktiviert Ihr Konto nicht und löscht keine Einträge. Prüf- und Freigabe-Aufbewahrung müssen gesondert geprüft werden.",
